@asynccontextmanager
async def lifespan(app: FastAPI):
    """Initialize and shut down the process-wide PostHog client."""
    settings = get_settings()
    posthog_client = build_client(settings)
    posthog_log_provider = None

    if posthog_client is not None:
        if not is_pytest():
            posthog_log_provider = configure_posthog_log_export(
                settings.posthog_api_key or "", settings.posthog_host or ""
            )
        atexit.register(posthog_client.shutdown)
    elif settings.debug and settings.posthog_enabled:
        missing_var = "POSTHOG_API_KEY" if not settings.posthog_api_key else "POSTHOG_HOST"
        raise RuntimeError(
            f"{missing_var} variable required by PostHog is missing or un-configured, "
            f"this causes events to be silently missed. This error stops appearing once "
            f"{missing_var} is configured"
        )

    app.state.posthog_client = posthog_client
    yield

    if posthog_client:
        posthog_client.shutdown()
    if posthog_log_provider:
        posthog_log_provider.shutdown()

